mkdir -p /tmp/w 2>/dev/null; cd "C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/44586b9f-03e1-4b03-8523-201e45adf5a9/scratchpad" && cat > idx.py <<'EOF'
import re,sys,glob,yaml,json
S="C:/visual projects/wol-study/docs/spec/"
rows={}
for fn in glob.glob(S+"*.md"):
    for ln,l in enumerate(open(fn,encoding='utf8'),1):
        if l.startswith('|') and 'Источник' in l:
            cells=[c.strip() for c in l.strip().strip('|').split('|')]
            m=re.search(r'Источник:\s*([^|]*)$',cells[-1])
            if not m: continue
            for tok in re.findall(r'[A-Za-z_][A-Za-z0-9_.]*',m.group(1)):
                rows.setdefault(tok,[]).append((fn.split('/')[-1],ln,cells))
json.dump(rows,open('specidx.json','w'),ensure_ascii=False)
D="C:/visual projects/reverse-kit/pipeline/_work/run_wol2/records/collections/"
for p in ['08','09','10','11']:
    d=yaml.safe_load(open(D+f"c-fsm_catalogs.part{p}.yaml",encoding='utf8'))
    miss=[];hit=0
    for c in d['candidates']:
        short=c['type'].split('.')[-1]
        if short in rows: hit+=1
        else: miss.append(c['type'])
    print(p,hit,len(miss),miss)
EOF
python idx.py

cd "C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/44586b9f-03e1-4b03-8523-201e45adf5a9/scratchpad" && cat > q.py <<'EOF'
import json,sys
r=json.load(open('specidx.json',encoding='utf8'))
for t in sys.argv[1:]:
    for f,ln,c in r.get(t,[]):
        print(t,f,ln,len(c)); 
        for i,x in enumerate(c): print('  ',i,x[:300])
EOF
PYTHONIOENCODING=utf8 python q.py ThunderDash UseAirWave | head -60; PYTHONIOENCODING=utf8 python - <<'EOF'
import json,collections
r=json.load(open('specidx.json',encoding='utf8'))
c=collections.Counter(v[0][0] for v in r.values()); print(c)
EOF

