	}
	private new void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this)
		{
			multiAnimIdle = true
		});
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new PauseState("Pause", fsm, this));
