		if (lastAttackInfo != null && !lastAttackInfo.isStatusEffect)
			hitCounter++;
		hurtStopwatchID = ChaosStopwatch.Begin(Mathf.Min(maxHurtDuration, durationIncreaseMultiplier * baseHurtDuration / (float)hitCounter + ChaosStopwatc
	public virtual void HandleStunEffect()
		if (base.stunEffect == null)
